1=1

    AND t.fd_operation = #{fdOperation}


    AND t.fd_dock_no like concat('%',#{fdDockNo},'%')


    AND t.fd_dock_name like concat('%',#{fdDockName},'%')


    and exists (select 1 from safety_enter_filing_per_history p where p.filing_id=t.id and p.fd_per_name  = #{fdPerName})


    and exists (select 1 from safety_enter_filing_per_history p where p.filing_id=t.id and p.fd_per_card =#{fdPerCard})


    and exists (select 1 from safety_enter_filing_per_history p where p.filing_id=t.id and p.fd_per_phone =#{fdPerPhone})


    and exists (select 1 from safety_enter_filing_per_history p where p.filing_id=t.id and p.fd_per_type_code=#{fdPerType})


    AND t.fd_car_no like concat('%',#{fdCarNo},'%')


    and FIND_IN_SET (#{fdFilingFactory},t.fd_filing_factory_code)


    AND t.fd_filing_type = #{fdFilingType}


    AND t.fd_state = #{fdState}


    AND t.fd_supplier_name = #{fdSupplierName}


    AND t.fd_goods_name like concat('%',#{fdGoodsName},'%')


    AND t.fd_driver_name like concat('%',#{fdDriverName},'%')


    AND t.fd_filing_begin <= #{fdFilingBegin}


    AND t.fd_filing_end >= #{fdFilingEnd}


    AND t.create_time >= #{createTimeBegin}


    AND t.create_time <= #{createTimeEnd}


    AND t.fd_dock_no = #{isAdmin}


    and t.fd_operation_user_code like concat('%',#{handler},'%')


    and t.fd_filing_car_type_name = #{fdFilingCarTypeName}

mapper.select:
select t.id as fd_filing_id,t.fd_state,t.fd_state_code, t.fd_filing_type_code,t.fd_filing_type,t.fd_enter_type_code,t.fd_enter_type, t.fd_filing_factory_code,t.fd_filing_factory, date_format(t.fd_filing_begin,'%Y-%m-%d') fd_filing_begin, date_format(t.fd_filing_end,'%Y-%m-%d') fd_filing_end, t.fd_supplier_name,t.fd_supplier_code,t.fd_goods_name,t.fd_goods_weight, t.fd_dock_no,t.fd_dock_name,t.fd_dock_department,t.fd_dock_phone, t.fd_remark,date_format(t.create_time,'%Y-%m-%d %H:%i:%s') create_time,t.create_user, t.fd_goods_update_time, t.fd_car_no,p.fd_car_belong,p.fd_driver_name,p.fd_protect_grade,p.fd_detailed_img,p.fd_vin, p.fd_engine,p.fd_car_img,p.fd_car_date,
a.approve_code,a.approve_name, a.fd_filing_factory_code as approve_filing_factory_code, a.fd_filing_factory as approve_filing_factory, date_format(a.fd_filing_begin,'%Y-%m-%d') approve_filing_begin, date_format(a.fd_filing_end,'%Y-%m-%d') approve_filing_end, t.fd_filing_car_type,t.fd_filing_car_type_name
from safety_enter_filing t left join safety_enter_protect p on t.fd_car_no=p.fd_car_no left join safety_enter_filing_approve a on t.id=a.fd_filing_id where t.id=#{filingId}
